/**
 * @name Trace pickle file source
 * @description Trace where the file object passed to pickle.load comes from
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-file-source
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleFileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleFileFlow = TaintTracking::Global<PickleFileConfig>;
import PickleFileFlow::PathGraph

from PickleFileFlow::PathNode source, PickleFileFlow::PathNode sink
where PickleFileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle load from $@.", source.getNode(), "parameter"

/**
 * @name Path Traversal in FileResponse
 * @description Detects if user input flows into aiohttp.web.FileResponse path argument
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the first argument to aiohttp.web.FileResponse
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("FileResponse").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"
